import fs from 'fs';
import path from 'path';
import {
  RIVET_PAGE_SHELL_DIRECTORY,
  RIVET_PAGE_SHELL_FILES,
} from './utils/rivetPage';

const ensureRivetPageShells = (): void => {
  fs.mkdirSync(RIVET_PAGE_SHELL_DIRECTORY, { recursive: true });
  for (const shellFile of RIVET_PAGE_SHELL_FILES) {
    const builtShell = path.join(RIVET_PAGE_SHELL_DIRECTORY, shellFile);
    if (!fs.existsSync(builtShell)) {
      fs.copyFileSync(path.join(__dirname, 'ui', shellFile), builtShell);
    }
  }
};

export default ensureRivetPageShells;
